712      *   & predicted_branch_i, branch_mispredict_i can only be asserted before or on the same cycle
713      *   as seeing fetch_valid & fetch_ready). When branch_mispredict_i is asserted, fetch_valid may
714      *   be asserted in response. If fetch_valid is asserted on the same cycle as
715      *   branch_mispredict_i this indicates the fetch_fifo/icache has the not-taken side of the
716      *   branch immediately ready for use
717      */
718     logic        predicted_branch_live_q, predicted_branch_live_d;
719     logic [31:0] predicted_branch_nt_pc_q, predicted_branch_nt_pc_d;
720     logic [31:0] awaiting_instr_after_mispredict_q, awaiting_instr_after_mispredict_d;
721     logic [31:0] next_pc;
722 
723     logic mispredicted, mispredicted_d, mispredicted_q;
724 
725     assign next_pc = fetch_addr + (instr_is_compressed_out ? 32'd2 : 32'd4);
726 
727     logic predicted_branch;
728 
729     // pc_set_i takes precendence over branch prediction
730     assign predicted_branch = predict_branch_taken & ~pc_set_i;
731 
732     always_comb begin
733       predicted_branch_live_d = predicted_branch_live_q;
734       mispredicted_d          = mispredicted_q;
735 
736       if (branch_req & predicted_branch) begin
737         predicted_branch_live_d = 1'b1;
738         mispredicted_d          = 1'b0;
739       end else if (predicted_branch_live_q) begin
740         if (fetch_valid & fetch_ready) begin
741           predicted_branch_live_d = 1'b0;
742         end else if (nt_branch_mispredict_i) begin
743           mispredicted_d = 1'b1;
744         end
745       end
746     end
747 
748     always @(posedge clk_i or negedge rst_ni) begin
749       if (!rst_ni) begin
750         predicted_branch_live_q <= 1'b0;
751         mispredicted_q          <= 1'b0;
752       end else begin
753         predicted_branch_live_q <= predicted_branch_live_d;
754         mispredicted_q          <= mispredicted_d;
755       end
756     end
757 
758     always @(posedge clk_i) begin
759       if (branch_req & predicted_branch) begin
760         predicted_branch_nt_pc_q <= next_pc;
761       end
762     end
