764     // Must only see mispredict after we've performed a predicted branch but before we've accepted
765     // any instruction (with fetch_ready & fetch_valid) that follows that predicted branch.
766     `ASSERT(MispredictOnlyImmediatelyAfterPredictedBranch,
767       nt_branch_mispredict_i |-> predicted_branch_live_q)
